'use client'

import { type ComponentStates } from '@polymorph/react'
import { Histogram } from './Histogram'

/**
 * States fixture, from `design/components/histogram.md`'s States table.
 *
 * The data is Relay's, because sample data sets the product's tone. It is
 * generated by arithmetic, not listed or randomised. Random data would draw a
 * different shape on every render, and the shape is what the chart shows.
 */

/**
 * One week of first-response minutes, n = 240: most under 10, with a shoulder
 * out to 45. This two-population shape (quick triage, escalated queues) is what
 * the chart shows and a mean would hide.
 */
const FIRST_RESPONSE: number[] = [
  // The bulk: 200 responses spread over 0–10 minutes.
  ...Array.from({ length: 200 }, (_, index) => Math.round(((index * 7919) % 1000) / 10) / 10),
  // The shoulder: 40 escalations spread over 10–45.
  ...Array.from({ length: 40 }, (_, index) => 10 + Math.round(((index * 104729) % 3500) / 10) / 10),
]

/**
 * Resolution hours with a long right tail: most tickets close within four
 * hours and a few take days. A mean would hide this asymmetry.
 */
const RESOLUTION_HOURS: number[] = [
  ...Array.from({ length: 150 }, (_, index) => Math.round(((index * 31) % 400) / 10) / 10),
  // The tail: quadratic, so it thins as it reaches toward 72.
  ...Array.from({ length: 30 }, (_, index) => 4 + Math.round((index / 30) ** 2 * 680) / 10),
]

/** A new queue: fourteen observations. Sturges gives about 5 bins, and nothing is smoothed. */
const FEW: number[] = [2.1, 3.4, 3.8, 4.2, 5.0, 5.5, 6.1, 6.8, 7.2, 8.0, 9.4, 11.2, 12.8, 14.5]

/** Order values in dollars, for the currency format's "$0–$25" ranges. */
const ORDER_VALUES: number[] = Array.from(
  { length: 120 },
  (_, index) => ((index * 53) % 140) + ((index * 17) % 23),
)

export const states: ComponentStates = {
  component: 'Histogram',

  entries: [
    {
      name: 'first-response minutes',
      render: () => (
        <Histogram
          data={FIRST_RESPONSE}
          x={{ label: 'Minutes to first response' }}
          label="First response time, this week"
        />
      ),
      expect: { 'data-size': 'md' },
    },
    {
      name: 'skewed',
      render: () => (
        <Histogram
          data={RESOLUTION_HOURS}
          x={{ label: 'Hours to resolution' }}
          label="Resolution time, this month"
        />
      ),
    },
    {
      name: 'few points',
      render: () => (
        <Histogram data={FEW} x={{ label: 'Minutes' }} label="First responses, new queue" />
      ),
    },
    {
      name: 'bins override',
      render: () => (
        <Histogram
          data={FIRST_RESPONSE}
          bins={20}
          x={{ label: 'Minutes to first response' }}
          label="First response time, the finer read"
        />
      ),
    },
    {
      name: 'format',
      render: () => (
        <Histogram
          data={ORDER_VALUES}
          x={{ label: 'Order value', format: { style: 'currency', currency: 'USD' } }}
          label="Order values"
        />
      ),
    },
    {
      name: 'empty',
      render: () => <Histogram data={[]} label="First response time, this week" />,
      expect: { 'data-state': 'empty' },
    },
    {
      name: 'loading',
      render: () => (
        <Histogram data={FIRST_RESPONSE} loading label="First response time, this week" />
      ),
      expect: { 'data-state': 'loading' },
    },
    {
      // `false` removes the visual layer only: the keyboard reading position,
      // its announcements and the table twin all stay.
      name: 'tooltip off',
      render: () => (
        <Histogram data={FIRST_RESPONSE} tooltip={false} label="First response time, print" />
      ),
    },
    {
      // With `onSelect`: the summary names the activation, and an agent can pick a bin.
      name: 'selectable',
      render: () => (
        <Histogram
          data={FIRST_RESPONSE}
          x={{ label: 'Minutes to first response' }}
          label="First response time, this week"
          onSelect={() => {}}
        />
      ),
    },
  ],

  requiredSelectors: [
    "[data-state='empty']",
    "[data-state='loading']",
    '[data-active]',
    ':focus-visible',
  ],
}
